import { useMemo, useState } from "react";
import { Link } from "wouter";
import { useAuth } from "@/_core/hooks/useAuth";
import { startLogin } from "@/const";
import { trpc } from "@/lib/trpc";
import { Streamdown } from "streamdown";
import {
  Activity, ArrowLeft, ArrowUpRight, BookOpen, Bot, Boxes, BrainCircuit, Bug, Check, ChevronLeft, CircleUserRound, Code2, Cpu, Database, FileCode2, Filter, Gauge, Heart, LayoutDashboard, Library, LockKeyhole, LogOut, Menu, MessageSquare, Network, Plus, Radio, Search, Send, ShieldAlert, ShoppingBag, ShoppingCart, Sparkles, Terminal, UserPlus, Users, Wrench, X, Zap,
} from "lucide-react";
import { toast } from "sonner";

type Section = "dashboard" | "profile" | "learning" | "tracks" | "cves" | "malware" | "tools" | "community" | "market" | "ai" | "admin";

function SectionIcon({ section }: { section: Section }) {
  const icons = { dashboard: LayoutDashboard, profile: CircleUserRound, learning: Library, tracks: Network, cves: ShieldAlert, malware: Bug, tools: Wrench, community: Users, market: ShoppingBag, ai: Bot, admin: Gauge };
  const Icon = icons[section];
  return <Icon size={17} strokeWidth={1.8} />;
}

export default function Home() {
  const { user, loading, error: authError, isAuthenticated, logout } = useAuth();
  const [section, setSection] = useState<Section>("dashboard");
  const [mobileOpen, setMobileOpen] = useState(false);
  const [courseSearch, setCourseSearch] = useState("");
  const [cveSearch, setCveSearch] = useState("");
  const [severity, setSeverity] = useState<"all" | "critical" | "high" | "medium" | "low">("all");
  const [toolSearch, setToolSearch] = useState("");
  const [toolCategory, setToolCategory] = useState("all");
  const [toolSort, setToolSort] = useState<"name" | "category" | "recent">("name");
  const [bookSort, setBookSort] = useState<"title" | "price" | "recent">("recent");
  const [bookSearch, setBookSearch] = useState("");
  const [bookCategory, setBookCategory] = useState("all");
  const [bookMaxPoints, setBookMaxPoints] = useState("");
  const [cvePage, setCvePage] = useState(1);
  const [malwareSearch, setMalwareSearch] = useState("");
  const [malwareCategory, setMalwareCategory] = useState("all");
  const [postText, setPostText] = useState("");
  const [aiInput, setAiInput] = useState("");
  const [aiMessages, setAiMessages] = useState<{ role: "assistant" | "user"; content: string }[]>([
    { role: "assistant", content: "أنا NEXUS. اطرح سؤالًا عن مسار التعلم أو تحليل ثغرة أو أداة دفاعية، وسأبني لك إجابة قابلة للتنفيذ داخل نطاق مصرح به." },
  ]);

  const courseInput = useMemo(() => ({ search: courseSearch || undefined }), [courseSearch]);
  const cveInput = useMemo(() => ({ search: cveSearch || undefined, severity: severity === "all" ? undefined : severity }), [cveSearch, severity]);
  const toolInput = useMemo(() => ({ search: toolSearch || undefined, category: toolCategory, sort: toolSort }), [toolSearch, toolCategory, toolSort]);
  const bookInput = useMemo(() => ({ search: bookSearch || undefined, category: bookCategory, maxPoints: bookMaxPoints ? Number(bookMaxPoints) : undefined, sort: bookSort }), [bookSearch, bookCategory, bookMaxPoints, bookSort]);
  const paginatedCveInput = useMemo(() => ({ search: cveSearch || undefined, severity: severity === "all" ? undefined : severity, page: cvePage, pageSize: 10 }), [cveSearch, severity, cvePage]);
  const dashboard = trpc.dashboard.useQuery(undefined, { enabled: isAuthenticated });
  const coursesQuery = trpc.courses.list.useQuery(courseInput);
  const roadmapsQuery = trpc.roadmaps.list.useQuery();
  const tracksQuery = trpc.tracks.list.useQuery();
  const cvesQuery = trpc.cves.list.useQuery(cveInput);
  const paginatedCvesQuery = trpc.cves.paginated.useQuery(paginatedCveInput);
  const toolsQuery = trpc.tools.advanced.useQuery(toolInput);
  const postsQuery = trpc.community.feed.useQuery();
  const friendRequestsQuery = trpc.community.friendRequests.useQuery(undefined, { enabled: isAuthenticated });
  const booksQuery = trpc.market.booksAdvanced.useQuery(bookInput);
  const cartQuery = trpc.market.cart.useQuery(undefined, { enabled: isAuthenticated });
  const notificationsQuery = trpc.notifications.list.useQuery(undefined, { enabled: isAuthenticated });
  const nvdStatusQuery = trpc.nvd.status.useQuery();
  const malwareQuery = trpc.malware.list.useQuery({ search: malwareSearch || undefined, category: malwareCategory === "all" ? undefined : malwareCategory });
  const createPost = trpc.community.create.useMutation({ onSuccess: () => { setPostText(""); postsQuery.refetch(); toast.success("تم بث الإشارة إلى المجتمع"); } });
  const likePost = trpc.community.like.useMutation({ onSuccess: () => postsQuery.refetch() });
  const followUser = trpc.community.follow.useMutation({ onSuccess: data => toast.success(data.following ? "تمت المتابعة" : "تم إلغاء المتابعة") });
  const sendFriendRequest = trpc.community.sendFriendRequest.useMutation({ onSuccess: () => toast.success("تم إرسال طلب الصداقة") });
  const respondFriendRequest = trpc.community.respondFriendRequest.useMutation({ onSuccess: () => { friendRequestsQuery.refetch(); toast.success("تم تحديث طلب الصداقة"); } });
  const progressMutation = trpc.courses.progress.useMutation({ onSuccess: () => { dashboard.refetch(); toast.success("تم حفظ التقدم"); } });
  const addToCart = trpc.market.addToCart.useMutation({ onSuccess: () => { cartQuery.refetch(); toast.success("تمت إضافة العنصر إلى السلة"); } });
  const removeFromCart = trpc.market.removeFromCart.useMutation({ onSuccess: () => cartQuery.refetch() });
  const askAI = trpc.ai.ask.useMutation({ onSuccess: data => { setAiMessages(messages => [...messages, { role: "assistant", content: data.answer }]); }, onError: () => toast.error("تعذر الوصول إلى NEXUS الآن") });

  const courses = coursesQuery.data ?? [];
  const cves = paginatedCvesQuery.data?.items ?? cvesQuery.data ?? [];
  const tools = toolsQuery.data ?? [];
  const cartCount = cartQuery.data?.reduce((total, item) => total + item.quantity, 0) ?? 0;
  const unreadCount = notificationsQuery.data?.filter(item => !item.isRead).length ?? 0;
  const stats = dashboard.data ?? { points: 640, coursesCompleted: 3, activeCourses: 2, cvesTracked: cves.length, followers: 128 };
  const syncError = authError || coursesQuery.error || cvesQuery.error || toolsQuery.error || postsQuery.error || booksQuery.error || roadmapsQuery.error || tracksQuery.error;

  const navItems: { id: Section; label: string; meta?: string }[] = [
    { id: "dashboard", label: "الرئيسية", meta: "01" },
    { id: "profile", label: "الملف الشخصي", meta: "ID" },
    { id: "learning", label: "الدورات", meta: "02" },
    { id: "tracks", label: "Tracks / Roadmaps", meta: "03" },
    { id: "cves", label: "مركز الثغرات CVE", meta: "04" },
    { id: "malware", label: "مركز Malware", meta: "05" },
    { id: "tools", label: "دليل الأدوات", meta: "04" },
    { id: "community", label: "المجتمع", meta: "05" },
    { id: "market", label: "السوق والكتب", meta: `${cartCount}` },
  ];
  if (user?.role === "admin") navItems.push({ id: "admin", label: "غرفة المدير", meta: "A" });

  const navigate = (target: Section) => { setSection(target); setMobileOpen(false); };
  const titleMap: Record<Section, string> = { dashboard: "CYBERJOCX", profile: "YOUR PROFILE", learning: "مسارات التعلّم", tracks: "مساراتك التعليمية", cves: "مركز الثغرات CVE", malware: "مركز Malware", tools: "دليل الأدوات", community: "المجتمع", market: "مكتبة CyberJocx", ai: "NEXUS", admin: "إدارة المنصة" };

  if (loading) return <div className="boot-screen"><div className="boot-panel"><div className="boot-line">[BOOT] initializing identity layer...</div><div className="boot-line">[BOOT] mounting cyberjocx interface...</div><div className="skeleton-heading" /><div className="skeleton-grid"><i /><i /><i /></div><div className="boot-cursor">█</div></div></div>;

  return (
    <div className="app-shell">
      <aside className={`side-panel ${mobileOpen ? "is-open" : ""}`}>
        <div className="brand-block">
          <div className="brand-mark"><span>◩</span><span>◫</span></div>
          <div><div className="brand-name"><span className="brand-accent">C</span>YBER<span className="brand-accent">J</span>OCX</div><div className="brand-sub">SECURITY // LEARNING OS</div></div>
          <button className="mobile-close" onClick={() => setMobileOpen(false)}><X size={18} /></button>
        </div>
        <div className="status-chip"><span className="pulse-dot" /> CYBERJOCX <b>ONLINE</b></div>
        <div className="nav-caption">// NAVIGATION</div>
        <nav className="main-nav">
          {navItems.map(item => <button key={item.id} className={`nav-item ${section === item.id ? "active" : ""}`} onClick={() => navigate(item.id)}><SectionIcon section={item.id} /><span>{item.label}</span><em>{item.meta}</em></button>)}
        </nav>
        <div className="sidebar-terminal"><div className="terminal-title"><Terminal size={13} /> LIVE FEED</div><p><span>&gt;</span> threat intel stream connected</p><p><span>&gt;</span> 4 new learning nodes</p><p><span>&gt;</span> encryption layer active</p></div>
        <div className="side-footer"><div className="mini-avatar">{user?.name?.[0] ?? "G"}</div><div className="user-meta"><strong>{user?.name ?? "GHOST_OPERATOR"}</strong><span>{user?.role === "admin" ? "ADMIN // ROOT" : "FIELD AGENT"}</span></div>{isAuthenticated ? <button className="icon-button" title="تسجيل الخروج" onClick={() => logout()}><LogOut size={15} /></button> : <button className="icon-button" title="تسجيل الدخول" onClick={() => startLogin()}><LockKeyhole size={15} /></button>}</div>
      </aside>
      {mobileOpen && <button className="mobile-overlay" onClick={() => setMobileOpen(false)} aria-label="إغلاق القائمة" />}
      <main className="main-panel">
        <header className="topbar"><button className="mobile-menu" onClick={() => setMobileOpen(true)}><Menu size={19} /></button><div className="breadcrumb"><span>CYBERJOCX</span><ChevronLeft size={14} /><b>{titleMap[section]}</b></div><div className="topbar-actions"><span className="top-time">23:47:08 UTC</span><button className="alert-button" onClick={() => toast.info(unreadCount ? `${unreadCount} إشعارات غير مقروءة` : "لا توجد إشعارات جديدة")}><Radio size={16} /><span className="alert-ping" /></button><button className="profile-trigger" onClick={() => navigate("profile")}><span className="mini-avatar">{user?.name?.[0] ?? "G"}</span><span>{user?.name ?? "GHOST_OPERATOR"}</span></button></div></header>
        <div className="content-wrap">
          <div className="page-heading"><div><div className="eyebrow"><span /> {section === "dashboard" ? "WELCOME BACK" : "WELCOME TO CYBERJOCX"}</div><h1>{titleMap[section]}</h1><p>{section === "dashboard" ? "راقب تقدمك، اجمع نقاطك، ووسّع مساحة معرفتك داخل الشبكة." : "محتوى واضح وخطوات عملية تساعدك على التعلّم وبناء خبرة قابلة للقياس."}</p></div></div>
          {syncError && <div className="system-alert"><ShieldAlert size={15} /><span>{authError ? "AUTH WARNING // تعذر إكمال جلسة Google. تأكد من السماح بالكوكيز ثم أعد المحاولة." : "SYNC WARNING // تعذر مزامنة بعض الإشارات. ستظهر آخر نسخة متاحة ويمكن إعادة المحاولة تلقائيًا."}</span></div>}
          {section === "dashboard" && <DashboardView stats={stats} courses={courses} cves={cves} onNavigate={navigate} />}
          {section === "profile" && <ProfileView user={user} />}
          {section === "learning" && <LearningView courses={courses} roadmaps={roadmapsQuery.data ?? []} tracks={tracksQuery.data ?? []} loading={coursesQuery.isLoading || roadmapsQuery.isLoading || tracksQuery.isLoading} error={coursesQuery.error || roadmapsQuery.error || tracksQuery.error} search={courseSearch} setSearch={setCourseSearch} onStart={course => isAuthenticated ? progressMutation.mutate({ courseId: course.id, progress: 10 }) : startLogin()} />}
          {section === "tracks" && <TracksView tracks={tracksQuery.data ?? []} loading={tracksQuery.isLoading} error={tracksQuery.error} />}
          {section === "cves" && <CvesView cves={cves} loading={cvesQuery.isLoading || paginatedCvesQuery.isLoading} error={cvesQuery.error || paginatedCvesQuery.error} search={cveSearch} setSearch={value => { setCveSearch(value); setCvePage(1); }} severity={severity} setSeverity={value => { setSeverity(value); setCvePage(1); }} page={cvePage} totalPages={paginatedCvesQuery.data?.totalPages ?? 0} onPage={setCvePage} lastUpdated={nvdStatusQuery.data?.lastCompletedAt ? new Date(nvdStatusQuery.data.lastCompletedAt).toLocaleString("ar-EG") : nvdStatusQuery.data?.lastStatus ?? "لم تبدأ بعد"} />}
          {section === "malware" && <MalwareView items={malwareQuery.data ?? []} loading={malwareQuery.isLoading} error={malwareQuery.error} search={malwareSearch} setSearch={setMalwareSearch} category={malwareCategory} setCategory={setMalwareCategory} />}
          {section === "tools" && <ToolsView tools={tools} loading={toolsQuery.isLoading} error={toolsQuery.error} search={toolSearch} setSearch={setToolSearch} category={toolCategory} setCategory={setToolCategory} sort={toolSort} setSort={setToolSort} />}
          {section === "community" && <CommunityView posts={postsQuery.data ?? []} requests={friendRequestsQuery.data ?? []} loading={postsQuery.isLoading} error={postsQuery.error} postText={postText} setPostText={setPostText} onPost={() => isAuthenticated ? createPost.mutate({ content: postText }) : startLogin()} onLike={postId => isAuthenticated ? likePost.mutate({ postId }) : startLogin()} onFollow={userId => isAuthenticated ? followUser.mutate({ userId }) : startLogin()} onFriend={userId => isAuthenticated ? sendFriendRequest.mutate({ userId }) : startLogin()} onRespond={(requestId, accept) => respondFriendRequest.mutate({ requestId, accept })} />}
          {section === "market" && <MarketView books={booksQuery.data ?? []} loading={booksQuery.isLoading} error={booksQuery.error} cartItems={cartQuery.data ?? []} cartCount={cartCount} onAdd={bookId => isAuthenticated ? addToCart.mutate({ bookId }) : startLogin()} onRemove={itemId => removeFromCart.mutate({ itemId })} search={bookSearch} setSearch={setBookSearch} category={bookCategory} setCategory={setBookCategory} maxPoints={bookMaxPoints} setMaxPoints={setBookMaxPoints} sort={bookSort} setSort={setBookSort} />}
          {section === "ai" && <AIView messages={aiMessages} input={aiInput} setInput={setAiInput} onAsk={() => { if (!aiInput.trim()) return; setAiMessages(messages => [...messages, { role: "user", content: aiInput }]); askAI.mutate({ message: aiInput, history: aiMessages }); setAiInput(""); }} isLoading={askAI.isPending} isAuthenticated={isAuthenticated} />}
          {section === "admin" && <AdminView />} 
        </div>
        <button className="nexus-float" onClick={() => navigate("ai")} aria-label="فتح محادثة NEXUS"><span className="nexus-bot"><Bot size={23} /></span><span className="nexus-float-label">NEXUS<br /><small>اسألني</small></span></button>
      </main>
    </div>
  );
}

function DashboardView({ stats, courses, cves, onNavigate }: { stats: { points: number; coursesCompleted: number; activeCourses: number; cvesTracked: number; followers: number }; courses: any[]; cves: any[]; onNavigate: (section: Section) => void }) {
  return <div className="dashboard-grid">
    <section className="hero-card panel-card"><div className="hero-grid" /><div className="hero-copy"><div className="section-tag">[ YOUR PROFILE ]</div><h2>Stay curious.<br /><span>Stay dangerous.</span></h2><p>المعرفة هي طبقة الحماية الأولى. اختر نقطة دخول، اختبر فهمك، واترك أثرًا نظيفًا داخل النظام.</p><button className="primary-button" onClick={() => onNavigate("learning")}>استكشف المسارات <ArrowUpRight size={16} /></button></div><div className="hero-orbit"><div className="orbit-ring ring-one" /><div className="orbit-ring ring-two" /><div className="orbit-core"><ShieldAlert size={30} /><span>NX</span></div><span className="orbit-label label-a">THREAT</span><span className="orbit-label label-b">DEFENSE</span><span className="orbit-label label-c">INTEL</span></div><div className="hero-footer"><span><Activity size={13} /> LAST SYNC: 00:02:14 AGO</span><span>ENCRYPTION: AES-256 <Check size={13} /></span></div></section>
    <section className="stat-card points-card panel-card"><div className="stat-icon cyan"><Zap size={19} /></div><div className="stat-label">TOTAL XP / POINTS</div><div className="stat-number">{stats.points.toLocaleString()}</div><div className="stat-trend"><ArrowUpRight size={13} /> +12.4% <span>this cycle</span></div><div className="sparkline"><i /><i /><i /><i /><i /><i /><i /><i /><i /><i /><i /></div></section>
    <section className="stat-card panel-card"><div className="stat-icon purple"><BookOpen size={19} /></div><div className="stat-label">COURSES COMPLETED</div><div className="stat-number">{String(stats.coursesCompleted).padStart(2, "0")}</div><div className="stat-sub">{stats.activeCourses} active learning nodes</div><div className="progress-line"><span style={{ width: `${Math.min(88, stats.coursesCompleted * 18 + 22)}%` }} /></div></section>
    <section className="stat-card panel-card"><div className="stat-icon red"><Bug size={19} /></div><div className="stat-label">CVE INTELLIGENCE</div><div className="stat-number">{stats.cvesTracked || cves.length}</div><div className="stat-sub danger-text"><span className="pulse-dot red-dot" /> 03 critical alerts tracked</div></section>
    <section className="activity-card panel-card"><div className="card-head"><div><div className="section-tag">// CONTINUE LEARNING</div><h3>Active learning nodes</h3></div><button className="text-button" onClick={() => onNavigate("learning")}>VIEW ALL <ArrowUpRight size={14} /></button></div><div className="course-list">{courses.slice(0, 3).map((course, index) => <div className="course-row" key={course.id}><div className={`course-thumb thumb-${index + 1}`}><span>{index === 0 ? "WEB" : index === 1 ? "SOC" : "THRT"}</span></div><div className="course-row-main"><div className="course-row-meta">{course.category} <span>•</span> {course.level}</div><strong>{course.title}</strong><div className="course-row-progress"><span style={{ width: `${[72, 38, 14][index]}%` }} /></div></div><div className="course-percent">{[72, 38, 14][index]}%</div></div>)}</div></section>
    <section className="activity-card panel-card"><div className="card-head"><div><div className="section-tag">// THREAT RADAR</div><h3>Latest CVE signals</h3></div><button className="text-button" onClick={() => onNavigate("cves")}>OPEN RADAR <ArrowUpRight size={14} /></button></div><div className="cve-mini-list">{cves.slice(0, 3).map(cve => <div className="cve-mini" key={cve.id}><span className={`severity-dot ${cve.severity}`} /><div><strong>{cve.cveNumber}</strong><span>{cve.title}</span></div><b>{cve.cvss}</b></div>)}</div><div className="radar-footer"><span><span className="pulse-dot" /> LIVE FEED</span><span>Updated 4m ago</span></div></section>
    <section className="quote-card panel-card"><div className="quote-mark">“</div><p>Security is not a product. It is a process of staying one step ahead of the unknown.</p><span>// NEXUS PROTOCOL 01</span></section>
    <section className="quick-card panel-card"><div className="section-tag">// QUICK ACCESS</div><div className="quick-grid"><button onClick={() => onNavigate("ai")}><Bot size={18} /><span>Ask NEXUS</span><ArrowUpRight size={13} /></button><button onClick={() => onNavigate("tools")}><Wrench size={18} /><span>Toolbox</span><ArrowUpRight size={13} /></button><button onClick={() => onNavigate("community")}><MessageSquare size={18} /><span>Community</span><ArrowUpRight size={13} /></button><button onClick={() => onNavigate("market")}><ShoppingCart size={18} /><span>Market</span><ArrowUpRight size={13} /></button></div></section>
  </div>;
}

function ModuleState({ title, error, empty = false }: { title: string; error?: unknown; empty?: boolean }) {
  return <div className="empty-state panel-card"><Activity size={27} /><h3>{error ? "Signal unavailable" : empty ? "No nodes indexed" : "Syncing matrix..."}</h3><p>{error ? "تعذر الوصول إلى قاعدة البيانات. تحقق من الاتصال وحاول مرة أخرى." : empty ? title : "جارٍ تحميل البيانات الدائمة من طبقة المعرفة..."}</p></div>;
}

function ProfileView({ user }: { user: any }) {
  const [name, setName] = useState(user?.name ?? "");
  const [bio, setBio] = useState(user?.bio ?? "");
  const [avatarUrl, setAvatarUrl] = useState(user?.avatarUrl ?? "");
  const [bannerUrl, setBannerUrl] = useState(user?.bannerUrl ?? "");
  const [phone, setPhone] = useState(user?.phone ?? "");
  const [linkedinUrl, setLinkedinUrl] = useState(user?.linkedinUrl ?? "");
  const [rank, setRank] = useState(user?.memberRank ?? "learner");
  const [primaryTrackId, setPrimaryTrackId] = useState(String(user?.primaryTrackId ?? ""));
  const tracks = trpc.tracks.list.useQuery();
  const profile = trpc.profile.byId.useQuery({ userId: user?.id ?? 0 }, { enabled: Boolean(user?.id) });
  const friends = trpc.community.friends.useQuery(undefined, { enabled: Boolean(user?.id) });
  const updateProfile = trpc.profile.update.useMutation({ onSuccess: () => { profile.refetch(); toast.success("تم حفظ ملفك الشخصي"); } });
  const uploadMedia = trpc.profile.uploadMedia.useMutation({ onSuccess: (data, variables) => { if (variables.kind === "avatar") setAvatarUrl(data.url); else setBannerUrl(data.url); toast.success("تم رفع الصورة بنجاح"); } });
  const pickMedia = (kind: "avatar" | "banner", file?: File) => { if (!file) return; if (!file.type.startsWith("image/")) return toast.error("اختر ملف صورة صالحًا."); const reader = new FileReader(); reader.onload = () => uploadMedia.mutate({ kind, dataUrl: String(reader.result) }); reader.readAsDataURL(file); };
  const posts = profile.data?.posts ?? [];
  return <section className="profile-layout"><div className="profile-card panel-card"><div className="profile-cover" style={bannerUrl ? { backgroundImage: `linear-gradient(90deg, rgba(3,10,14,.55), rgba(45,11,59,.45)), url(${bannerUrl})` } : undefined}><div className="profile-scan" /><label className="media-upload banner-upload">تغيير البانر <input type="file" accept="image/png,image/jpeg,image/webp" onChange={event => pickMedia("banner", event.target.files?.[0])} /></label></div><div className="profile-body"><div className="profile-identity"><div className="profile-avatar avatar-photo">{avatarUrl ? <img src={avatarUrl} alt="صورة الحساب" /> : name?.[0] ?? "G"}<label className="media-upload avatar-upload"><Plus size={14} /><input type="file" accept="image/png,image/jpeg,image/webp" onChange={event => pickMedia("avatar", event.target.files?.[0])} /></label></div><div><div className="section-tag">// YOUR IDENTITY</div><h2>{name || "GHOST_OPERATOR"}</h2><span>{user?.email ?? "البريد غير متاح"} · {rank.toUpperCase()}</span></div></div><div className="profile-stats"><div><strong>{user?.points ?? 640}</strong><span>XP POINTS</span></div><div><strong>{rank.toUpperCase()}</strong><span>MEMBER RANK</span></div><div><strong>{posts.length}</strong><span>POSTS</span></div></div></div></div><div className="profile-editor panel-card"><div className="section-tag">// EDIT YOUR PROFILE</div><h3>رتّب هويتك وسجلّك المهني.</h3><p className="profile-helper">البريد والهاتف وLinkedIn بيانات خاصة لحسابك ولا تظهر في الملف العام تلقائيًا.</p><div className="profile-form-grid"><label className="admin-field"><span>الاسم المعروض</span><input value={name} onChange={event => setName(event.target.value)} placeholder="اسمك داخل CyberJocx" /></label><label className="admin-field"><span>الهاتف</span><input value={phone} onChange={event => setPhone(event.target.value)} placeholder="01xxxxxxxxx" /></label><label className="admin-field"><span>LinkedIn URL</span><input value={linkedinUrl} onChange={event => setLinkedinUrl(event.target.value)} placeholder="https://linkedin.com/in/..." /></label><label className="admin-field"><span>التصنيف</span><select value={rank} onChange={event => setRank(event.target.value)}><option value="learner">Learner</option><option value="contributor">Contributor</option><option value="analyst">Analyst</option><option value="mentor">Mentor</option><option value="elite">Elite</option></select></label><label className="admin-field"><span>المسار الأساسي</span><select value={primaryTrackId} onChange={event => setPrimaryTrackId(event.target.value)}><option value="">اختر مسارك</option>{tracks.data?.map(track => <option key={track.id} value={track.id}>{track.title}</option>)}</select></label><label className="admin-field full"><span>نبذة شخصية</span><textarea value={bio} onChange={event => setBio(event.target.value)} placeholder="اكتب ما تتعلمه وما المجال الذي تبني فيه خبرتك..." /></label></div><button className="primary-button" onClick={() => updateProfile.mutate({ name, bio, avatarUrl: avatarUrl || undefined, bannerUrl: bannerUrl || undefined, phone: phone || undefined, linkedinUrl: linkedinUrl || undefined, memberRank: rank as "learner" | "contributor" | "analyst" | "mentor" | "elite", primaryTrackId: primaryTrackId ? Number(primaryTrackId) : undefined })} disabled={updateProfile.isPending || uploadMedia.isPending}><Check size={15} /> حفظ الملف</button></div><div className="profile-posts panel-card"><div className="card-head"><div><div className="section-tag">// YOUR POSTS</div><h3>منشوراتك داخل المجتمع</h3></div><span>{posts.length} POSTS</span></div>{posts.length ? posts.map((post: any) => <article className="profile-post" key={post.id}><p>{post.content}</p><span>{new Date(post.createdAt).toLocaleDateString("ar-EG")} · {post.likesCount} إعجاب</span></article>) : <div className="empty-state"><MessageSquare size={21} /><p>لم تنشر أي إشارة بعد. ابدأ من صفحة المجتمع.</p></div>}</div><div className="profile-friends panel-card"><div className="card-head"><div><div className="section-tag">// YOUR CIRCLE</div><h3>الأصدقاء</h3></div><span>{friends.data?.length ?? 0} FRIENDS</span></div>{friends.data?.length ? <div className="friend-grid">{friends.data.map(friend => <div className="friend-card" key={friend.id}>{friend.avatarUrl ? <img src={friend.avatarUrl} alt="" /> : <span>{friend.name?.[0] ?? "C"}</span>}<div><strong>{friend.name ?? "عضو CyberJocx"}</strong><small>{friend.memberRank ?? "learner"}</small></div></div>)}</div> : <div className="empty-state"><Users size={21} /><p>لا يوجد أصدقاء بعد. أرسل طلبًا من صفحة المجتمع.</p></div>}</div></section>;
}

function LearningView({ courses, roadmaps, tracks, loading, error, search, setSearch, onStart }: { courses: any[]; roadmaps: any[]; tracks: any[]; loading: boolean; error?: unknown; search: string; setSearch: (value: string) => void; onStart: (course: any) => void }) {
  const [selectedCourseId, setSelectedCourseId] = useState<number | null>(null);
  const [roadmapTrackId, setRoadmapTrackId] = useState<number | null>(null);
  const [personalRoadmap, setPersonalRoadmap] = useState("");
  const [openLevelQuizId, setOpenLevelQuizId] = useState<number | null>(null);
  const [levelQuizAnswers, setLevelQuizAnswers] = useState<Record<number, number[]>>({});
  const courseInput = useMemo(() => ({ id: selectedCourseId ?? 0 }), [selectedCourseId]);
  const courseDetail = trpc.courses.byId.useQuery(courseInput, { enabled: selectedCourseId !== null });
  const roadmapDetail = trpc.tracks.roadmap.useQuery({ trackId: roadmapTrackId ?? 0 }, { enabled: roadmapTrackId !== null });
  const personalizeRoadmap = trpc.ai.personalizeRoadmap.useMutation({ onSuccess: data => setPersonalRoadmap(data.roadmap), onError: error => toast.error(error.message || "سجل دخولك لتخصيص roadmap.") });
  const submitLevelQuiz = trpc.tracks.submitQuiz.useMutation({ onSuccess: result => { roadmapDetail.refetch(); toast.success(result.passed ? `أحسنت، صدرت شهادتك: ${result.certificateCode}` : `النتيجة ${result.score}%، راجع المتطلبات وحاول مجددًا.`); } });
  if (loading) return <ModuleState title="جارٍ مزامنة مسارات التعلم..." />;
  if (error) return <ModuleState title="تعذر تحميل مسارات التعلم." error={error} />;
  if (!courses.length) return <ModuleState title="لم تتم فهرسة أي دورة بعد." empty />;
  const trackForCourse = selectedCourseId ? tracks.find(track => track.courses?.some((course: any) => course.id === selectedCourseId)) : undefined;
  return <section className="module-stack"><div className="module-toolbar"><div className="search-box"><Search size={17} /><input value={search} onChange={event => setSearch(event.target.value)} placeholder="ابحث في المسارات..." /></div><span className="result-count">{courses.length} NODES FOUND</span></div><div className="learning-banner panel-card"><div><div className="section-tag">// CAREER ROADMAPS</div><h2>{roadmaps[0]?.title ?? "Build your operator path."}</h2><p>اضغط على أي دورة لمشاهدة roadmap كامل للمسار، ومستويات الخبرة، ومتطلبات العبور.</p></div><div className="roadmap-steps">{roadmaps[0]?.courses?.length ? roadmaps[0].courses.slice(0, 3).map((course: any, index: number) => <span key={course.id} className={course.progress >= 100 ? "done" : index === 0 ? "active" : ""}>{`0${index + 1}`} / {course.title} <b>{course.progress}%</b></span>) : <span>01 / ROADMAP EMPTY</span>}</div></div><div className="course-cards">{courses.map((course, index) => <article className="course-card panel-card" key={course.id} onClick={() => setSelectedCourseId(course.id)} onKeyDown={event => event.key === "Enter" && setSelectedCourseId(course.id)} role="button" tabIndex={0}><div className={`course-art art-${(index % 3) + 1}`}><span className="art-code">{`0${index + 1}`}</span><div className="art-grid" /><div className="art-icon">{index === 0 ? <Code2 size={34} /> : index === 1 ? <Network size={34} /> : <BrainCircuit size={34} />}</div></div><div className="course-card-content"><div className="course-row-meta">{course.category} <span>•</span> {course.level}</div><h3>{course.title}</h3><p>{course.description}</p><div className="course-card-foot"><span><BookOpen size={14} /> {course.lessons} lessons</span><span><Activity size={14} /> {Math.round(course.durationMinutes / 60)}h</span><button className="small-button" onClick={event => { event.stopPropagation(); onStart(course); }}>START NODE <ArrowUpRight size={13} /></button></div></div></article>)}</div>{selectedCourseId !== null && <div className="modal-backdrop" onClick={() => setSelectedCourseId(null)}><div className="detail-modal panel-card" onClick={event => event.stopPropagation()}><button className="modal-close" onClick={() => setSelectedCourseId(null)}><X size={16} /></button><div className="section-tag">// COURSE NODE {courseDetail.isLoading ? "SYNCING" : "LOADED"}</div><h2>{courseDetail.data?.title ?? "Course detail"}</h2><p>{courseDetail.data?.description ?? "جارٍ تحميل تفاصيل عقدة التعلم..."}</p><div className="detail-meta"><span>{courseDetail.data?.category ?? "LEARNING"}</span><span>{courseDetail.data?.level ?? "FIELD"}</span><span>{courseDetail.data?.lessons ?? "--"} lessons</span></div><div className="modal-actions"><button className="primary-button" onClick={() => { const course = courseDetail.data ?? courses.find(item => item.id === selectedCourseId); if (course) onStart(course); }}><Zap size={15} /> ابدأ الدورة</button>{trackForCourse && <button className="small-button" onClick={() => { setPersonalRoadmap(""); setRoadmapTrackId(trackForCourse.id); }}>عرض Roadmap المسار <ArrowUpRight size={13} /></button>}</div></div></div>}{roadmapTrackId !== null && <div className="modal-backdrop" onClick={() => setRoadmapTrackId(null)}><div className="detail-modal panel-card roadmap-modal" onClick={event => event.stopPropagation()}><button className="modal-close" onClick={() => setRoadmapTrackId(null)}><X size={16} /></button><div className="section-tag">// FULL TRACK ROADMAP</div><h2>{roadmapDetail.data?.track.title ?? "جارٍ تحميل المسار"}</h2><p>خطة واضحة من المبتدئ حتى الاحتراف. أكمل متطلبات المستوى واختباره لتحصل على شهادته.</p><button className="secondary-button" disabled={personalizeRoadmap.isPending} onClick={() => personalizeRoadmap.mutate({ trackId: roadmapTrackId })}><Bot size={15} /> {personalizeRoadmap.isPending ? "NEXUS يجهز الخطة..." : "خصص الخطة مع NEXUS"}</button>{personalRoadmap && <div className="nexus-roadmap panel-card"><div className="section-tag">// NEXUS PERSONAL PLAN</div><Streamdown>{personalRoadmap}</Streamdown></div>}<div className="level-roadmap">{roadmapDetail.data?.levels.map((level: any) => <article key={level.id} className={`level-node ${level.active ? "active" : ""} ${level.completed ? "completed" : ""}`}><div className="level-node-head"><b>{String(level.orderIndex).padStart(2, "0")}</b><div><h3>{level.title}</h3><span>{level.certificateName}</span></div>{level.completed && <Check size={17} />}</div><p>{level.description}</p><div className="level-requirements"><strong>للتجاوز:</strong> {level.requirements}</div>{level.modules.map((module: any) => <div className="video-module" key={module.id}><div><strong>{module.title}</strong><p>{module.description}</p><small>{module.actionItems}</small></div>{module.videoUrl && <a href={module.videoUrl} target="_blank" rel="noreferrer" className="small-button"><Activity size={13} /> شاهد الفيديو</a>}</div>)}{level.quiz && <div className="level-quiz"><button className="small-button" onClick={() => setOpenLevelQuizId(openLevelQuizId === level.quiz.id ? null : level.quiz.id)}>{level.certificate ? "عرض شهادتك" : "اختبار المستوى"} <Check size={13} /></button>{openLevelQuizId === level.quiz.id && <div className="quiz-panel"><h3>{level.quiz.title}</h3>{level.quiz.questions.map((question: any, index: number) => <fieldset key={question.id}><legend>{index + 1}. {question.prompt}</legend>{JSON.parse(question.optionsJson).map((option: string, optionIndex: number) => <label key={option}><input type="radio" name={`level-${level.quiz.id}-${question.id}`} checked={(levelQuizAnswers[level.quiz.id] ?? [])[index] === optionIndex} onChange={() => setLevelQuizAnswers(current => ({ ...current, [level.quiz.id]: (() => { const next = [...(current[level.quiz.id] ?? [])]; next[index] = optionIndex; return next; })() }))} /> {option}</label>)}</fieldset>)}<button className="primary-button compact" disabled={submitLevelQuiz.isPending || (levelQuizAnswers[level.quiz.id] ?? []).length !== level.quiz.questions.length} onClick={() => submitLevelQuiz.mutate({ quizId: level.quiz.id, answers: levelQuizAnswers[level.quiz.id] ?? [] })}>إرسال الإجابات</button>{level.certificate && <div className="certificate-card"><Check size={18} /><div><strong>شهادة المستوى صادرة</strong><span>{level.certificate.certificateCode}</span></div></div>}</div>}</div>}</article>)}</div></div></div>}</section>;
}

function TracksView({ tracks, loading, error }: { tracks: any[]; loading: boolean; error?: unknown }) {
  const [selectedTrackId, setSelectedTrackId] = useState<number | null>(null);
  const [answers, setAnswers] = useState<number[]>([]);
  const detail = trpc.tracks.progress.useQuery({ trackId: selectedTrackId ?? 0 }, { enabled: selectedTrackId !== null });
  const submitQuiz = trpc.tracks.submitQuiz.useMutation({ onSuccess: result => { detail.refetch(); toast.success(result.passed ? `نجحت في الاختبار — الشهادة ${result.certificateCode ?? "جاهزة"}` : `النتيجة ${result.score}% — راجع الدروس وحاول مرة أخرى`); } });
  if (loading) return <ModuleState title="جارٍ مزامنة الـtracks والـroadmaps..." />;
  if (error) return <ModuleState title="تعذر تحميل الـtracks." error={error} />;
  if (!tracks.length) return <ModuleState title="لم تتم إضافة أي track بعد." empty />;
  return <section className="module-stack"><div className="learning-banner panel-card"><div><div className="section-tag">// OPERATOR ROADMAP</div><h2>اختر طريقك داخل النظام.</h2><p>كل track يوضح المهارات، الدورات، الأدوات، ونسبة تقدمك حتى الشهادة.</p></div><div className="roadmap-steps"><span className="active">01 / SELECT TRACK</span><span>02 / COMPLETE NODES</span><span>03 / EARN CERTIFICATE</span></div></div><div className="track-grid">{tracks.map((track: any) => { const progress = track.courses?.length ? Math.round(track.courses.reduce((sum: number, course: any) => sum + course.progress, 0) / track.courses.length) : 0; return <article className="track-card panel-card" key={track.id}><div className="section-tag">// {track.slug}</div><h3>{track.title}</h3><p>{track.description}</p><div className="track-progress"><div><span>TRACK PROGRESS</span><b>{progress}%</b></div><i><em style={{ width: `${progress}%` }} /></i></div><div className="track-course-list">{track.courses?.map((course: any, index: number) => <div className="track-course-row" key={course.id}><span>{`0${index + 1}`}</span><strong>{course.title}</strong><b>{course.progress}%</b></div>)}</div><div className="track-tools">{track.tools?.slice(0, 5).map((tool: any) => <span key={tool.id}>{tool.name}</span>)}</div><div className="track-outcome"><span>OUTCOME</span><p>{track.outcome}</p></div><button className="primary-button compact" onClick={() => { setSelectedTrackId(track.id); setAnswers([]); }}>OPEN PROGRESS CONSOLE <ArrowUpRight size={13} /></button></article>; })}</div>{selectedTrackId !== null && <div className="modal-backdrop" onClick={() => setSelectedTrackId(null)}><div className="detail-modal panel-card track-detail-modal" onClick={event => event.stopPropagation()}><button className="modal-close" onClick={() => setSelectedTrackId(null)}><X size={16} /></button><div className="section-tag">// PROGRESS CONSOLE {detail.isLoading ? "SYNCING" : "LIVE"}</div><h2>{detail.data?.track.title ?? "Track dashboard"}</h2><p>{detail.data?.track.description ?? "جارٍ تحميل خطة المسار..."}</p><div className="detail-progress-hero"><strong>{detail.data?.averageProgress ?? 0}%</strong><span>متوسط إتمام المسار</span></div><div className="progress-milestones">{detail.data?.courses?.map((course: any, index: number) => <div key={course.id}><span>{String(index + 1).padStart(2, "0")}</span><div><strong>{course.title}</strong><small>{course.progress}% مكتمل</small></div><i><em style={{ width: `${course.progress}%` }} /></i></div>)}</div>{detail.data?.quiz ? <div className="quiz-panel"><div className="section-tag">// KNOWLEDGE CHECK // PASS {detail.data!.quiz!.passingScore}%</div><h3>{detail.data!.quiz!.title}</h3>{detail.data!.quiz!.questions.map((question: any, index: number) => <fieldset key={question.id}><legend>{index + 1}. {question.prompt}</legend>{JSON.parse(question.optionsJson).map((option: string, optionIndex: number) => <label key={option}><input type="radio" name={`q-${question.id}`} checked={answers[index] === optionIndex} onChange={() => setAnswers(current => { const next = [...current]; next[index] = optionIndex; return next; })} /> {option}</label>)}</fieldset>)}<button className="primary-button" disabled={answers.length !== detail.data!.quiz!.questions.length || submitQuiz.isPending} onClick={() => submitQuiz.mutate({ quizId: detail.data!.quiz!.id, answers })}><Check size={15} /> SUBMIT ASSESSMENT</button>{detail.data.attempts?.[0] && <span className="quiz-last-result">آخر نتيجة: {detail.data.attempts[0].score}%</span>}</div> : <div className="empty-state"><BrainCircuit size={22} /><p>لم تتم إضافة اختبار لهذا المسار بعد.</p></div>}{detail.data?.certificate && <div className="certificate-card"><Check size={20} /><div><strong>شهادة إتمام صادرة</strong><span>{detail.data.certificate.certificateCode} · {new Date(detail.data.certificate.issuedAt).toLocaleDateString("ar-EG")}</span></div></div>}</div></div>}</section>;
}

function CvesView({ cves, loading, error, search, setSearch, severity, setSeverity, page, totalPages, onPage, lastUpdated }: { cves: any[]; loading: boolean; error?: unknown; search: string; setSearch: (value: string) => void; severity: string; setSeverity: (value: any) => void; page: number; totalPages: number; onPage: (value: number) => void; lastUpdated?: string }) {
  const [selectedCveId, setSelectedCveId] = useState<number | null>(null);
  const cveInput = useMemo(() => ({ id: selectedCveId ?? 0 }), [selectedCveId]);
  const cveDetail = trpc.cves.byId.useQuery(cveInput, { enabled: selectedCveId !== null });
  if (loading) return <ModuleState title="جارٍ مزامنة مركز CVE..." />;
  if (error) return <ModuleState title="تعذر تحميل إشارات CVE." error={error} />;
  if (!cves.length) return <ModuleState title="لم تتم فهرسة أي CVE بعد." empty />;
  return <section className="module-stack"><div className="module-toolbar"><div className="search-box wide"><Search size={17} /><input value={search} onChange={event => setSearch(event.target.value)} placeholder="ابحث برقم CVE أو المنتج أو العنوان..." /></div><div className="filter-tabs"><Filter size={15} />{["all", "critical", "high", "medium", "low"].map(value => <button key={value} className={severity === value ? "active" : ""} onClick={() => setSeverity(value)}>{value.toUpperCase()}</button>)}</div><div className="sync-meta">NVD SYNC {lastUpdated ?? "DAILY"}</div></div><div className="intel-banner panel-card"><div className="intel-glyph"><Bug size={28} /></div><div><div className="section-tag">// CVE INTELLIGENCE TERMINAL</div><h2>Know the weakness before it knows you.</h2><p>قاعدة بحث موحدة لإشارات الثغرات. فلتر حسب الخطورة وتحقق من المصدر قبل اتخاذ أي إجراء.</p></div><div className="intel-stat"><strong>{cves.length}</strong><span>signals indexed</span></div></div><div className="cve-table panel-card"><div className="table-head"><span>IDENTIFIER</span><span>THREAT VECTOR</span><span>SEVERITY</span><span>CVSS</span><span>DATE</span><span /></div>{cves.map(cve => <div className="table-row" key={cve.id} onClick={() => setSelectedCveId(cve.id)} role="button" tabIndex={0} onKeyDown={event => event.key === "Enter" && setSelectedCveId(cve.id)}><div className="cve-id"><span className={`severity-dot ${cve.severity}`} /><strong>{cve.cveNumber}</strong></div><div><strong>{cve.title}</strong><span>{cve.affected}</span></div><div><span className={`severity-pill ${cve.severity}`}>{cve.severity.toUpperCase()}</span></div><div className="cvss-score">{cve.cvss}</div><div className="muted-cell">{cve.publishedDate}</div><a href={cve.sourceUrl ?? "https://nvd.nist.gov/"} target="_blank" rel="noreferrer" className="row-link" onClick={event => event.stopPropagation()}><ArrowUpRight size={15} /></a></div>)}</div><div className="pagination-bar"><span>PAGE {page} / {Math.max(totalPages, 1)}</span><button className="small-button" disabled={page <= 1} onClick={() => onPage(Math.max(1, page - 1))}>PREV</button><button className="small-button" disabled={!totalPages || page >= totalPages} onClick={() => onPage(Math.min(totalPages, page + 1))}>NEXT</button></div>{selectedCveId !== null && <div className="modal-backdrop" onClick={() => setSelectedCveId(null)}><div className="detail-modal panel-card cve-detail" onClick={event => event.stopPropagation()}><button className="modal-close" onClick={() => setSelectedCveId(null)}><X size={16} /></button><div className="section-tag">// CVE INTELLIGENCE {cveDetail.isLoading ? "SYNCING" : "LOADED"}</div><div className="cve-detail-id"><span className={`severity-dot ${cveDetail.data?.severity ?? "high"}`} /><span>{cveDetail.data?.cveNumber ?? "CVE SIGNAL"}</span><b>{cveDetail.data?.cvss ?? "--"} CVSS</b></div><h2>{cveDetail.data?.title ?? "Loading signal..."}</h2><p>{cveDetail.data?.description ?? "جارٍ تحميل تفاصيل الإشارة..."}</p><div className="detail-meta"><span>AFFECTED: {cveDetail.data?.affected ?? "--"}</span><span>PUBLISHED: {cveDetail.data?.publishedDate ?? "--"}</span></div><a className="primary-button" href={cveDetail.data?.sourceUrl ?? "https://nvd.nist.gov/"} target="_blank" rel="noreferrer">VERIFY SOURCE <ArrowUpRight size={15} /></a></div></div>}</section>;
}

function ToolsView({ tools, loading, error, search, setSearch, category, setCategory, sort, setSort }: { tools: any[]; loading: boolean; error?: unknown; search: string; setSearch: (value: string) => void; category: string; setCategory: (value: string) => void; sort: "name" | "category" | "recent"; setSort: (value: "name" | "category" | "recent") => void }) {
  if (loading) return <ModuleState title="جارٍ مزامنة دليل الأدوات..." />;
  if (error) return <ModuleState title="تعذر تحميل دليل الأدوات." error={error} />;
  if (!tools.length) return <ModuleState title="لم تتم فهرسة أي أداة بعد." empty />;
  const categories = ["all", ...Array.from(new Set(tools.map(tool => tool.category)))];
  return <section className="module-stack"><div className="module-toolbar"><div className="search-box wide"><Search size={17} /><input value={search} onChange={event => setSearch(event.target.value)} placeholder="ابحث في toolkit..." /></div><div className="filter-tabs"><Boxes size={15} />{categories.slice(0, 5).map(value => <button key={value} className={category === value ? "active" : ""} onClick={() => setCategory(value)}>{value.toUpperCase()}</button>)}</div><select className="sort-select" value={sort} onChange={event => setSort(event.target.value as "name" | "category" | "recent")}><option value="name">SORT: NAME</option><option value="category">SORT: CATEGORY</option><option value="recent">SORT: RECENT</option></select></div><div className="tools-grid">{tools.map((tool, index) => <article className="tool-card panel-card" key={tool.id}><div className="tool-card-top"><div className={`tool-icon tool-${index % 4}`}><Terminal size={20} /></div><span className="tool-category">{tool.category}</span><button className="ghost-icon"><ArrowUpRight size={15} /></button></div><h3>{tool.name}</h3><p>{tool.description}</p><div className="command-line"><span>$</span>{tool.commands ?? "secure-tool --help"}</div><a href={tool.downloadUrl ?? "#"} target="_blank" rel="noreferrer" className="tool-link">OPEN REPOSITORY <ArrowUpRight size={13} /></a></article>)}</div></section>;
}

function CommunityView({ posts, requests, loading, error, postText, setPostText, onPost, onLike, onFollow, onFriend, onRespond }: { posts: any[]; requests: any[]; loading: boolean; error?: unknown; postText: string; setPostText: (value: string) => void; onPost: () => void; onLike: (id: number) => void; onFollow: (id: number) => void; onFriend: (id: number) => void; onRespond: (id: number, accept: boolean) => void }) {
  if (loading) return <ModuleState title="جارٍ مزامنة إشارات المجتمع..." />;
  if (error) return <ModuleState title="تعذر تحميل المجتمع." error={error} />;
  return <section className="community-layout"><div className="community-main"><div className="compose-card panel-card"><div className="compose-avatar">◩</div><div className="compose-input"><textarea value={postText} onChange={event => setPostText(event.target.value)} placeholder="اكتب سؤالًا أو إنجازًا أو ملاحظة مفيدة للمجتمع..." /><div className="compose-foot"><span><Sparkles size={14} /> راجع المحتوى قبل النشر</span><button className="primary-button compact" disabled={!postText.trim()} onClick={onPost}>نشر <Send size={14} /></button></div></div></div>{posts.length ? posts.map((post: any) => <article className="post-card panel-card" key={post.id}><div className="post-head"><div className="post-avatar">{post.author?.[0] ?? "A"}</div><div><strong>{post.author ?? "عضو CyberJocx"}</strong><span>{new Date(post.createdAt).toLocaleDateString("ar-EG")}</span></div><button className="ghost-icon" onClick={() => post.userId && onFollow(post.userId)} title="متابعة المستخدم"><UserPlus size={15} /></button><button className="ghost-icon" onClick={() => post.userId && onFriend(post.userId)} title="إرسال طلب صداقة"><Users size={15} /></button></div><p className="post-content">{post.content}</p><div className="post-actions"><button onClick={() => onLike(post.id)}><Heart size={15} /> {post.likesCount ?? 0}</button><button><MessageSquare size={15} /> نقاش</button><button><ArrowUpRight size={15} /> مشاركة</button></div></article>) : <div className="empty-state panel-card"><MessageSquare size={27} /><h3>لا توجد منشورات بعد.</h3><p>كن أول من ينشر معلومة أو سؤالًا مفيدًا.</p></div>}</div><aside className="community-aside">{requests.length > 0 && <div className="topic-card panel-card"><div className="section-tag">// FRIEND REQUESTS</div>{requests.map(request => <div className="friend-request" key={request.id}><span>طلب من مستخدم #{request.senderId}</span><div><button className="small-button" onClick={() => onRespond(request.id, true)}>قبول</button><button className="ghost-icon" onClick={() => onRespond(request.id, false)}><X size={14} /></button></div></div>)}</div>}<div className="network-card panel-card"><div className="section-tag">// COMMUNITY PULSE</div><div className="network-number">1,284 <span>active learners</span></div><div className="network-bars"><i /><i /><i /><i /><i /><i /><i /><i /><i /><i /></div><div className="online-list"><span /><span /><span /><span /><span /><b>+1.2k online now</b></div></div><div className="topic-card panel-card"><div className="section-tag">// TOPICS</div>{["#threathunting", "#websecurity", "#blueteam", "#cve-watch"].map((topic, index) => <div className="topic-row" key={topic}><span>0{index + 1}</span><strong>{topic}</strong><em>{[284, 176, 98, 64][index]} signals</em></div>)}</div></aside></section>;
}

function MarketView({ books, loading, error, cartItems, cartCount, onAdd, onRemove, search, setSearch, category, setCategory, maxPoints, setMaxPoints, sort, setSort }: { books: any[]; loading: boolean; error?: unknown; cartItems: any[]; cartCount: number; onAdd: (id: number) => void; onRemove: (id: number) => void; search: string; setSearch: (value: string) => void; category: string; setCategory: (value: string) => void; maxPoints: string; setMaxPoints: (value: string) => void; sort: "title" | "price" | "recent"; setSort: (value: "title" | "price" | "recent") => void }) {
  const [cartOpen, setCartOpen] = useState(false);
  if (loading) return <ModuleState title="جارٍ مزامنة الأرشيف..." />;
  if (error) return <ModuleState title="تعذر تحميل السوق." error={error} />;
  if (!books.length) return <ModuleState title="لم تتم إضافة أي منتج إلى السوق بعد." empty />;
  const items = books;
  const categories = ["all", ...Array.from(new Set(books.map(book => book.category)))];
  return <section className="module-stack"><div className="market-banner panel-card"><div><div className="section-tag">// CYBERJOCX ARCHIVE</div><h2>Knowledge is the ultimate exploit.</h2><p>اشترِ بالـ XP، اجمع مراجعك، وابنِ مكتبة لا تنام.</p></div><button className="cart-button" onClick={() => setCartOpen(true)}><ShoppingCart size={17} /> CART <b>{cartCount}</b></button></div><div className="module-toolbar"><div className="search-box wide"><Search size={17} /><input value={search} onChange={event => setSearch(event.target.value)} placeholder="ابحث بالعنوان أو المؤلف أو الوصف..." /></div><div className="filter-tabs"><Filter size={15} />{categories.slice(0, 6).map(value => <button key={value} className={category === value ? "active" : ""} onClick={() => setCategory(value)}>{value.toUpperCase()}</button>)}</div><input className="points-filter" value={maxPoints} onChange={event => setMaxPoints(event.target.value.replace(/[^0-9]/g, ""))} placeholder="MAX XP" /><select className="sort-select" value={sort} onChange={event => setSort(event.target.value as "title" | "price" | "recent")}><option value="recent">SORT: RECENT</option><option value="title">SORT: TITLE</option><option value="price">SORT: XP</option></select></div><div className="book-grid">{items.map((book, index) => <article className="book-card panel-card" key={book.id}><div className={`book-cover book-${index % 3}`}><BookOpen size={32} /><span>ARCHIVE<br />VOL. 0{index + 1}</span></div><div className="book-content"><div className="course-row-meta">{book.category} ARCHIVE</div><h3>{book.title}</h3><p>{book.author}</p><div className="book-foot"><strong><Zap size={14} /> {book.pricePoints} XP</strong><button className="small-button" onClick={() => onAdd(book.id)}>ADD <Plus size={14} /></button></div></div></article>)}</div>{cartOpen && <div className="modal-backdrop" onClick={() => setCartOpen(false)}><div className="cart-modal panel-card" onClick={event => event.stopPropagation()}><button className="modal-close" onClick={() => setCartOpen(false)}><X size={16} /></button><div className="section-tag">// SHOPPING CART MATRIX</div><h2>Your archive queue.</h2>{cartItems.length ? <div className="cart-items">{cartItems.map(item => <div className="cart-item" key={item.id}><div><strong>{item.book?.title ?? `BOOK NODE ${item.bookId}`}</strong><span>{item.quantity} × {item.book?.pricePoints ?? 0} XP</span></div><button className="ghost-icon" onClick={() => onRemove(item.id)}><X size={15} /></button></div>)}</div> : <div className="cart-empty"><ShoppingCart size={22} /><p>السلة فارغة. أضف مرجعًا إلى قائمة الأرشيف.</p></div>}<div className="cart-total"><span>TOTAL NODES</span><strong>{cartCount}</strong></div></div></div>}</section>;
}

function MalwareView({ items, loading, error, search, setSearch, category, setCategory }: { items: any[]; loading: boolean; error?: unknown; search: string; setSearch: (value: string) => void; category: string; setCategory: (value: string) => void }) {
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const detail = trpc.malware.byId.useQuery({ id: selectedId ?? 0 }, { enabled: selectedId !== null });
  const categories = ["all", "Ransomware", "Loader / Banking Trojan", "Information Stealer", "Wiper"];
  if (loading) return <ModuleState title="جارٍ تحميل مركز Malware..." />;
  if (error) return <ModuleState title="تعذر تحميل بيانات Malware." error={error} />;
  return <section className="module-stack"><div className="module-toolbar"><div className="search-box wide"><Search size={17} /><input value={search} onChange={event => setSearch(event.target.value)} placeholder="ابحث باسم العائلة أو التقنية أو الوصف..." /></div><div className="filter-tabs"><Filter size={15} />{categories.map(value => <button key={value} className={category === value ? "active" : ""} onClick={() => setCategory(value)}>{value === "all" ? "الكل" : value}</button>)}</div><span className="result-count">{items.length} FAMILIES</span></div><div className="intel-banner panel-card"><div className="intel-glyph"><Bug size={28} /></div><div><div className="section-tag">// MALWARE INTELLIGENCE</div><h2>افهم السلوك قبل بناء الدفاع.</h2><p>مركز داخلي للعائلات الخبيثة والتقنيات المرتبطة بها، مخصص للبحث والتحليل والدفاع القانوني.</p></div></div>{items.length ? <div className="tools-grid">{items.map(item => <article className="tool-card panel-card" key={item.id} onClick={() => setSelectedId(item.id)} role="button" tabIndex={0} onKeyDown={event => event.key === "Enter" && setSelectedId(item.id)}><div className="tool-card-top"><div className="tool-icon tool-1"><Bug size={20} /></div><span className={`severity-pill ${item.severity}`}>{item.severity}</span></div><h3>{item.name}</h3><p>{item.description}</p><div className="command-line"><span>MITRE</span>{item.mitreTechniques}</div><div className="detail-meta"><span>TARGETS: {item.targets}</span></div><button className="tool-link" onClick={event => { event.stopPropagation(); setSelectedId(item.id); }}>عرض التفاصيل <ArrowUpRight size={13} /></button></article>)}</div> : <ModuleState title="لم تُفهرس عائلات Malware بهذه الفلاتر بعد." empty />}{selectedId !== null && <div className="modal-backdrop" onClick={() => setSelectedId(null)}><div className="detail-modal panel-card" onClick={event => event.stopPropagation()}><button className="modal-close" onClick={() => setSelectedId(null)}><X size={16} /></button><div className="section-tag">// MALWARE PROFILE</div><h2>{detail.data?.name ?? "جارٍ التحميل"}</h2><p>{detail.data?.description}</p><div className="detail-meta"><span>{detail.data?.category}</span><span>{detail.data?.severity}</span><span>{detail.data?.targets}</span></div><div className="command-line"><span>MITRE TECHNIQUES</span>{detail.data?.mitreTechniques}</div>{detail.data?.sourceUrl && <a href={detail.data.sourceUrl} target="_blank" rel="noreferrer" className="primary-button">فتح المرجع <ArrowUpRight size={14} /></a>}</div></div>}</section>;
}

function AIView({ messages, input, setInput, onAsk, isLoading, isAuthenticated }: { messages: { role: "assistant" | "user"; content: string }[]; input: string; setInput: (value: string) => void; onAsk: () => void; isLoading: boolean; isAuthenticated: boolean }) {
  return <section className="ai-layout"><div className="ai-chat panel-card"><div className="ai-chat-head"><div className="ai-orb"><Bot size={22} /></div><div><strong>NEXUS INTELLIGENCE</strong><span>AI LEARNING COPILOT // ONLINE</span></div><span className="ai-online"><span className="pulse-dot" /> READY</span></div><div className="messages">{messages.map((message, index) => <div className={`message-row ${message.role}`} key={index}><div className="message-avatar">{message.role === "assistant" ? <Bot size={15} /> : "G"}</div><div className="message-bubble">{message.role === "assistant" ? <Streamdown>{message.content}</Streamdown> : message.content}<span className="message-time">23:{42 + index}</span></div></div>)}{isLoading && <div className="typing"><span /><span /><span /> NEXUS is parsing signal...</div>}</div><div className="ai-input"><textarea value={input} onChange={event => setInput(event.target.value)} onKeyDown={event => { if (event.key === "Enter" && !event.shiftKey) { event.preventDefault(); onAsk(); } }} placeholder={isAuthenticated ? "اسأل NEXUS عن أي مفهوم..." : "سجّل الدخول لبدء جلسة مع NEXUS"} disabled={!isAuthenticated} /><button onClick={onAsk} disabled={!isAuthenticated || isLoading || !input.trim()}><Send size={17} /></button></div></div><aside className="ai-aside"><div className="ai-status panel-card"><div className="section-tag">// NEXUS CORE</div><div className="core-visual"><div className="core-ring r1" /><div className="core-ring r2" /><div className="core-dot"><Cpu size={20} /></div></div><h3>Context aware.</h3><p>المساعد يربط أسئلتك بالدورات والـ CVE والأدوات الموجودة في منظومتك.</p><div className="ai-tags"><span>LEARNING</span><span>DEFENSE</span><span>RESEARCH</span></div></div><div className="prompt-card panel-card"><div className="section-tag">// TRY ASKING</div>{["ما الفرق بين XSS و SSRF؟", "ابنِ لي خطة SOC خلال 30 يومًا", "كيف أقرأ CVSS بشكل صحيح؟"].map(prompt => <button key={prompt} onClick={() => setInput(prompt)}><span>&gt;</span>{prompt}</button>)}</div></aside></section>;
}

function AdminView() {
  const [mode, setMode] = useState<"course" | "tool" | "cve">("course");
  const [form, setForm] = useState<Record<string, string>>({});
  const adminStats = trpc.admin.stats.useQuery();
  const adminContent = trpc.admin.content.useQuery();
  const createCourse = trpc.admin.createCourse.useMutation({ onSuccess: () => { setForm({}); adminStats.refetch(); adminContent.refetch(); toast.success("تم نشر عقدة الدورة وإرسال إشعار للمستخدمين"); }, onError: error => toast.error(error.message) });
  const createTool = trpc.admin.createTool.useMutation({ onSuccess: () => { setForm({}); adminStats.refetch(); adminContent.refetch(); toast.success("تمت إضافة الأداة إلى الدليل"); }, onError: error => toast.error(error.message) });
  const createCve = trpc.admin.createCve.useMutation({ onSuccess: () => { setForm({}); adminStats.refetch(); adminContent.refetch(); toast.success("تمت فهرسة CVE وإرسال تنبيه الخطورة"); }, onError: error => toast.error(error.message) });
  const deleteCourse = trpc.admin.deleteCourse.useMutation({ onSuccess: () => { adminContent.refetch(); adminStats.refetch(); toast.success("تم حذف عقدة الدورة"); } });
  const deleteTool = trpc.admin.deleteTool.useMutation({ onSuccess: () => { adminContent.refetch(); adminStats.refetch(); toast.success("تم حذف الأداة"); } });
  const deleteCve = trpc.admin.deleteCve.useMutation({ onSuccess: () => { adminContent.refetch(); adminStats.refetch(); toast.success("تم حذف إشارة CVE"); } });
  const update = (key: string, value: string) => setForm(current => ({ ...current, [key]: value }));
  const submit = () => {
    if (mode === "course") createCourse.mutate({ title: form.title ?? "", slug: form.slug ?? (form.title ?? "").toLowerCase().replaceAll(" ", "-"), description: form.description ?? "", category: form.category ?? "WEB SECURITY", level: (form.level as "beginner" | "intermediate" | "advanced") ?? "beginner", instructor: form.instructor ?? "CYBERJOCX LAB", lessons: Number(form.lessons ?? 8), durationMinutes: Number(form.durationMinutes ?? 240) });
    if (mode === "tool") createTool.mutate({ name: form.name ?? "", category: form.category ?? "RECON", description: form.description ?? "", commands: form.commands, downloadUrl: form.downloadUrl });
    if (mode === "cve") createCve.mutate({ cveNumber: form.cveNumber ?? "", title: form.title ?? "", description: form.description ?? "", severity: (form.severity as "critical" | "high" | "medium" | "low") ?? "high", cvss: form.cvss ?? "7.5", publishedDate: form.publishedDate ?? new Date().toISOString().slice(0, 10), affected: form.affected ?? "Unknown", sourceUrl: form.sourceUrl });
  };
  const field = (key: string, label: string, placeholder: string) => <label className="admin-field"><span>{label}</span><input value={form[key] ?? ""} onChange={event => update(key, event.target.value)} placeholder={placeholder} /></label>;
  const stats = adminStats.data ?? { users: 1284, courses: 24, cves: 8492, tools: 64, posts: 382 };
  return <section className="admin-layout"><div className="admin-hero panel-card"><div className="section-tag">// ROOT ACCESS GRANTED</div><h2>Control the knowledge layer.</h2><p>إدارة المحتوى ومراجعة نبض المنصة من نقطة تحكم واحدة.</p><div className="admin-actions"><button className={`primary-button ${mode === "course" ? "" : "secondary-button"}`} onClick={() => setMode("course")}><BookOpen size={16} /> COURSE NODE</button><button className={`primary-button ${mode === "tool" ? "" : "secondary-button"}`} onClick={() => setMode("tool")}><Wrench size={16} /> TOOL NODE</button><button className={`primary-button ${mode === "cve" ? "" : "secondary-button"}`} onClick={() => setMode("cve")}><Bug size={16} /> CVE SIGNAL</button></div></div><div className="admin-metrics"><div className="admin-metric panel-card"><Users size={18} /><strong>{stats.users.toLocaleString()}</strong><span>REGISTERED OPERATORS</span></div><div className="admin-metric panel-card"><BookOpen size={18} /><strong>{stats.courses}</strong><span>COURSE NODES</span></div><div className="admin-metric panel-card"><Bug size={18} /><strong>{stats.cves.toLocaleString()}</strong><span>CVE SIGNALS</span></div><div className="admin-metric panel-card"><Wrench size={18} /><strong>{stats.tools}</strong><span>TOOL REPOSITORY</span></div></div><div className="admin-editor panel-card"><div className="card-head"><div><div className="section-tag">// WRITE TO KNOWLEDGE LAYER</div><h3>Publish {mode === "course" ? "course" : mode === "tool" ? "tool" : "CVE"} node</h3></div><span className="status-chip"><span className="pulse-dot" /> VALIDATED</span></div><div className="admin-form-grid">{mode === "course" && <>{field("title", "TITLE", "Threat Hunting Protocol")} {field("slug", "SLUG", "threat-hunting-protocol")} {field("category", "CATEGORY", "THREAT INTEL")} {field("instructor", "INSTRUCTOR", "NEXUS LAB")} {field("lessons", "LESSONS", "12")} {field("durationMinutes", "DURATION MINUTES", "360")}</>}{mode === "tool" && <>{field("name", "NAME", "Nmap")} {field("category", "CATEGORY", "RECON")} {field("commands", "COMMANDS", "nmap -sV --script safe target")} {field("downloadUrl", "REPOSITORY URL", "https://...")}</>}{mode === "cve" && <>{field("cveNumber", "CVE NUMBER", "CVE-2026-0000")} {field("title", "TITLE", "Critical signal title")} {field("severity", "SEVERITY", "critical")} {field("cvss", "CVSS", "9.8")} {field("affected", "AFFECTED PRODUCT", "Product / version")} {field("publishedDate", "PUBLISHED DATE", "2026-08-23")}</>}<label className="admin-field full"><span>DESCRIPTION</span><textarea value={form.description ?? ""} onChange={event => update("description", event.target.value)} placeholder="اكتب ملخصًا دقيقًا وقابلًا للتدقيق..." /></label></div><button className="primary-button" onClick={submit} disabled={createCourse.isPending || createTool.isPending || createCve.isPending}><Send size={15} /> PUBLISH TO MATRIX</button></div><div className="admin-table panel-card"><div className="card-head"><div><div className="section-tag">// CONTENT REGISTRY</div><h3>Current knowledge nodes</h3></div><span className="status-chip"><span className="pulse-dot" /> {adminContent.isLoading ? "SYNCING" : "LIVE"}</span></div><div className="registry-grid"><div><span className="registry-label">COURSES</span>{!adminContent.data?.courses.length && <div className="registry-empty">NO COURSE NODES</div>}{adminContent.data?.courses.map(item => <div className="registry-row" key={item.id}><strong>{item.title}</strong><span>{item.category}</span><button onClick={() => deleteCourse.mutate({ id: item.id })}><X size={13} /></button></div>)}</div><div><span className="registry-label">TOOLS</span>{adminContent.data?.tools.map(item => <div className="registry-row" key={item.id}><strong>{item.name}</strong><span>{item.category}</span><button onClick={() => deleteTool.mutate({ id: item.id })}><X size={13} /></button></div>)}</div><div><span className="registry-label">CVE SIGNALS</span>{adminContent.data?.cves.map(item => <div className="registry-row" key={item.id}><strong>{item.cveNumber}</strong><span>{item.severity}</span><button onClick={() => deleteCve.mutate({ id: item.id })}><X size={13} /></button></div>)}</div></div></div><div className="admin-table panel-card"><div className="card-head"><div><div className="section-tag">// RECENT ADMIN ACTIVITY</div><h3>Audit stream</h3></div><span className="status-chip"><span className="pulse-dot" /> MONITORING</span></div>{["Knowledge layer synchronized", "High-risk CVE notification pipeline ready", "Tool repository link verified", "Community signal review queue updated"].map((item, index) => <div className="audit-row" key={item}><span>0{index + 1}</span><strong>{item}</strong><em>{index + 2}m ago</em><Check size={15} /></div>)}</div></section>;
}
